window.BLOOM_EXAMPLE_SOURCES = {"python":"import logging\nimport subprocess\nfrom dataclasses import dataclass, field\n\nlogger = logging.getLogger(__name__)\n\n\ndef evaluate_preview(expression: str):\n    return eval(expression, {\"__builtins__\": {}})\n\n\n@dataclass\nclass Task:\n    command: str\n    done: bool = False\n    attempts: int = 0\n\n\n@dataclass\nclass TaskQueue:\n    tasks: list[Task] = field(default_factory=list)\n\n    def run_next(self, confirmed: bool = False) -> bool:\n        for task in self.tasks:\n            if task.done:\n                continue\n            if not confirmed:\n                return False\n            task.attempts += 1\n            result = subprocess.run(task.command, shell=True, capture_output=True)\n            if result.returncode:\n                logger.warning(\"Task failed: %s\", task.command)\n                return False\n            task.done = True\n            return True\n        return False\n","javascript":"\"use strict\";\nconst { execSync } = require(\"node:child_process\");\n/**\n * Bloom TypeScript/JS Stress Test\n * Testing: Interfaces, Types, Prototypes, Mutation, and Flow.\n */\nObject.defineProperty(exports, \"__esModule\", { value: true });\nclass HeavyLogicProcessor {\n    constructor(initial) {\n        this._state = initial;\n    }\n    async process(input) {\n        let result = input;\n        try {\n            if (result === undefined || result === null) {\n                throw new Error(\"Invalid Input\");\n            }\n            // Mutation Test\n            result = { ...result, processed: true };\n            this._state = result;\n            // Logic Test\n            const isValid = (this._state !== null) && (typeof result === 'object');\n            return isValid ? result : input;\n        }\n        catch (e) {\n            console.error(e);\n            return input;\n        }\n    }\n}\nHeavyLogicProcessor.VERSION = \"1.0.2\";\n// Prototype/Native test\nHeavyLogicProcessor.prototype.toString = function () {\n    return `[Processor ${this._state}]`;\n};\nconst myMap = new Map();\nmyMap.set(\"core\", new HeavyLogicProcessor({ data: 100 }));\n\nfunction reviewRiskyInput(source, command) {\n    const evaluated = eval(source);\n    execSync(command, { stdio: \"ignore\" });\n    return evaluated;\n}\n//# sourceMappingURL=stress_test.js.map\n","go":"package main\n\nimport (\n\t\"fmt\"\n\t\"os\"\n\t\"os/exec\"\n)\n\ntype Task struct {\n\tTitle string\n\tDone  bool\n}\n\nfunc complete(tasks []Task, title string) bool {\n\tfor index := range tasks {\n\t\tif tasks[index].Title == title {\n\t\t\ttasks[index].Done = true\n\t\t\treturn true\n\t\t}\n\t}\n\treturn false\n}\n\nfunc pendingTitles(tasks []Task) []string {\n\ttitles := make([]string, 0, len(tasks))\n\tfor _, task := range tasks {\n\t\tif !task.Done {\n\t\t\ttitles = append(titles, task.Title)\n\t\t}\n\t}\n\treturn titles\n}\n\nfunc removePath(path string) error {\n\treturn os.Remove(path)\n}\n\nfunc runShellCommand(command string) error {\n\treturn exec.Command(\"sh\", \"-c\", command).Run()\n}\n\nfunc main() {\n\ttasks := []Task{{Title: \"Review changes\"}, {Title: \"Publish package\"}}\n\tif !complete(tasks, \"Review changes\") {\n\t\tfmt.Println(\"Task was not found\")\n\t\treturn\n\t}\n\tfmt.Println(pendingTitles(tasks))\n}\n","rust":"use std::process::{Command, ExitStatus};\n\n#[derive(Debug)]\nstruct Task {\n    title: String,\n    done: bool,\n}\n\nfn complete(tasks: &mut [Task], title: &str) -> Result<(), String> {\n    let Some(task) = tasks.iter_mut().find(|task| task.title == title) else {\n        return Err(format!(\"Task not found: {title}\"));\n    };\n    task.done = true;\n    Ok(())\n}\n\nfn pending_titles(tasks: &[Task]) -> Vec<&str> {\n    tasks\n        .iter()\n        .filter(|task| !task.done)\n        .map(|task| task.title.as_str())\n        .collect()\n}\n\nunsafe fn read_raw_byte(pointer: *const u8) -> u8 {\n    std::ptr::read(pointer)\n}\n\nfn run_shell_command(command: &str) -> std::io::Result<ExitStatus> {\n    Command::new(\"sh\").arg(\"-c\").arg(command).status()\n}\n\nfn main() {\n    let mut tasks = vec![\n        Task { title: \"Review changes\".into(), done: false },\n        Task { title: \"Publish package\".into(), done: false },\n    ];\n\n    if let Err(error) = complete(&mut tasks, \"Review changes\") {\n        eprintln!(\"{error}\");\n        return;\n    }\n    println!(\"{:?}\", pending_titles(&tasks));\n}\n","lisp":"(defstruct task\n  id\n  title\n  (done-p nil))\n\n(defun make-queue ()\n  (vector (make-task :id 1 :title \"Review changes\")\n          (make-task :id 2 :title \"Publish package\")))\n\n(defun add-task (queue title)\n  (let ((clean-title (string-trim '(#\\Space #\\Tab) title)))\n    (when (plusp (length clean-title))\n      (concatenate 'vector queue\n        (vector (make-task :id (1+ (length queue)) :title clean-title))))))\n\n(defun complete-task (queue id)\n  (let ((found nil))\n    (let ((updated (map 'vector\n      (lambda (item)\n        (if (= (task-id item) id)\n            (progn (setf found t) (make-task :id id :title (task-title item) :done-p t))\n            item))\n      queue)))\n      (if found updated nil))))\n\n(defun pending-tasks (queue)\n  (remove-if #'task-done-p (coerce queue 'list)))\n\n(defun completed-count (queue)\n  (count-if #'task-done-p (coerce queue 'list)))\n\n(defun queue-summary (queue)\n  (format nil \"~d pending, ~d complete\"\n    (length (pending-tasks queue)) (completed-count queue)))\n\n(defun evaluate-form (form)\n  (eval form))\n\n(defun remove-task-file (pathname)\n  (delete-file pathname))\n\n(defun main ()\n  (let* ((queue (make-queue))\n         (completed (complete-task queue 1)))\n    (unless completed (error \"Task was not found\"))\n    (let ((expanded (add-task completed \"Write documentation\")))\n      (format t \"~a~%\" (queue-summary expanded))\n      (dolist (item (pending-tasks expanded))\n        (format t \"- ~a~%\" (task-title item))))))\n\n(main)\n","solidity":"// SPDX-License-Identifier: MIT\npragma solidity ^0.8.20;\n\ncontract TaskQueue {\n    struct Task {\n        uint256 id;\n        string title;\n        bool done;\n    }\n\n    Task[] private tasks;\n    mapping(uint256 => uint256) private indexById;\n    uint256 private nextId = 1;\n\n    event TaskAdded(uint256 indexed id, string title);\n    event TaskCompleted(uint256 indexed id);\n\n    function addTask(string calldata title) external returns (uint256) {\n        require(bytes(title).length > 0, \"Title is required\");\n        uint256 id = nextId++;\n        tasks.push(Task(id, title, false));\n        indexById[id] = tasks.length;\n        emit TaskAdded(id, title);\n        return id;\n    }\n\n    function completeTask(uint256 id) external {\n        uint256 index = indexById[id];\n        require(index > 0, \"Task was not found\");\n        Task storage task = tasks[index - 1];\n        require(!task.done, \"Task is already complete\");\n        task.done = true;\n        emit TaskCompleted(id);\n    }\n\n    function forward(address target, bytes calldata data) external returns (bool, bytes memory) {\n        require(msg.sender == tx.origin, \"Direct origin call required\");\n        (bool success, bytes memory result) = target.delegatecall(data);\n        return (success, result);\n    }\n\n    function getTask(uint256 id) external view returns (Task memory) {\n        uint256 index = indexById[id];\n        require(index > 0, \"Task was not found\");\n        return tasks[index - 1];\n    }\n\n    function taskCount() external view returns (uint256) {\n        return tasks.length;\n    }\n}\n"};
